{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, count(*) AS n, avg(value) AS avg_value, min(value) AS min_value, max(value) AS max_value FROM abnormal_metrics WHERE service_name='rate' AND metric IN ('k8s.deployment.available','k8s.deployment.desired') GROUP BY metric",
          "claim": "Rate deployment shows 0 available replicas for the entire abnormal window while 1 is desired."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' AS period, count(*) AS spans, min(CAST(time AS VARCHAR)) AS first_t, max(CAST(time AS VARCHAR)) AS last_t FROM normal_traces WHERE attr_k8s_service_name='rate' UNION ALL SELECT 'abnormal', count(*), min(CAST(time AS VARCHAR)), max(CAST(time AS VARCHAR)) FROM abnormal_traces WHERE attr_k8s_service_name='rate'",
          "claim": "Rate spans drop from 572 in normal to 6 in abnormal, all before 07:25:28.4, then stop."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) AS n, avg(duration)/1e6 AS avg_ms FROM abnormal_traces WHERE attr_k8s_service_name='search' AND attr_span_kind='Client' GROUP BY ALL ORDER BY 1,2",
          "claim": "Search's client calls to rate.Rate/GetRates return Error status in about 0.01 ms, 1100 times."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE attr_k8s_service_name='frontend' AND attr_span_kind='Server' AND span_name='HTTP /hotels' GROUP BY ALL",
          "claim": "Frontend HTTP /hotels server spans return 500 with Error status for 1101 requests, matching search's failures."
        }
      ]
    }
  ]
}
